"""rt_client.py  --  talks to an AgentCore RUNTIME (or to the offline 'practice runtime').   >>> YOU DO NOT EDIT THIS FILE <<<

A Runtime is a place where your AGENT CODE runs, hosted by AWS. You send it a prompt and a session id; it runs the agent in a private
sandbox for that session and sends back what the code returns. This file makes that call:
    boto3.client("bedrock-agentcore").invoke_agent_runtime(agentRuntimeArn=..., runtimeSessionId=..., payload=...)
The practice runtime imitates the same behaviour on your VM so you can see sessions and cold starts with no AWS.
"""
import json
import re
import time
import uuid
from pathlib import Path

import gw_agent
import gw_client as gc

HERE = Path(__file__).resolve().parent
SAVE = HERE / "my_runtime.json"                                                   # your Runtime ARN (never pushed to GitHub)
SIBLING = HERE.parent / "lab16a-askit-runtime" / "my_runtime.json"                # Lab 16B reads the one saved in Lab 16A
ARN_RE = re.compile(r"^arn:aws:bedrock-agentcore:[a-z0-9-]+:\d{12}:runtime/[A-Za-z0-9_-]+$")


def load_saved():
    for p in (SAVE, SIBLING):
        try:
            return json.loads(p.read_text(encoding="utf-8")).get("arn", "")
        except Exception:
            continue
    return ""


def save(arn):
    SAVE.write_text(json.dumps({"arn": arn.strip()}), encoding="utf-8")


def new_session_id():
    return "askit-session-" + uuid.uuid4().hex          # 46 characters: long enough and unique


def region_of(arn):
    m = re.match(r"^arn:aws:bedrock-agentcore:([a-z0-9-]+):", arn or "")
    return m.group(1) if m else "us-east-1"


class RtResult:
    def __init__(self, ok, answer="", steps=None, ms=0, tin=0, tout=0, cost=0.0, session=None, error="", raw=None):
        self.ok, self.answer, self.steps, self.ms, self.tin, self.tout, self.cost = ok, answer, steps or [], ms, tin, tout, cost
        self.session, self.error, self.raw = session or {}, error, raw


def agent_through(gateway, question, provider):
    """The AskIT agent finds its tools by asking a gateway, then calls them through it (same idea as Lab 15, Door 2)."""
    r = gateway.rpc("tools/list")
    tools = gc.tools_of(r)
    if not tools:
        return {"answer": f"(the agent could not list tools: {r.error})", "steps": [], "ms": r.ms, "tokens_in": 0, "tokens_out": 0, "cost_usd": 0.0}
    specs = [{"name": t["name"], "alias": t["name"].split("___")[-1], "description": t.get("description", ""),
              "schema": t.get("inputSchema") or {"type": "object", "properties": {}}} for t in tools]

    def call(name, args):
        rr = gateway.rpc("tools/call", {"name": name, "arguments": args})
        return gc.call_text(rr), rr.ms

    return gw_agent.run(question, provider, specs, call)


class PracticeRuntime:
    """Imitates a Runtime on your VM: one private 'sandbox' per session id, a slow first call (cold start), a fresh sandbox after idle time."""
    label = "Practice runtime (offline)"
    IDLE_SECONDS = 90          # the real default is minutes; short here so you can see it
    COLD_START_SECONDS = 1.3

    def __init__(self):
        self.sessions = {}

    def invoke(self, prompt, session_id, provider, gateway):
        t0 = time.time()
        now = time.time()
        s = self.sessions.get(session_id)
        cold = s is None or now - s["last"] > self.IDLE_SECONDS
        if cold:
            time.sleep(self.COLD_START_SECONDS)                                   # "start a new sandbox"
            s = {"boot_id": uuid.uuid4().hex[:8], "t0": time.time(), "turn": 0, "history": []}
            self.sessions[session_id] = s
        s["turn"] += 1
        if prompt.strip().lower() == "ping":                                     # a health check: no model, no tools
            r = {"answer": "pong 🏓 (the Runtime is alive)", "steps": [], "tokens_in": 0, "tokens_out": 0, "cost_usd": 0.0}
        else:
            r = agent_through(gateway, prompt, provider)
        s["history"].append({"q": prompt, "a": r["answer"]})
        s["last"] = time.time()
        sess = {"id": session_id, "boot_id": s["boot_id"], "turn": s["turn"], "cold": cold, "age_s": int(time.time() - s["t0"]), "history": len(s["history"])}
        return RtResult(True, r["answer"], r["steps"], int((time.time() - t0) * 1000), r["tokens_in"], r["tokens_out"], r["cost_usd"], sess)

    def make_idle(self, session_id):
        """Pretend the session has been quiet for longer than the idle limit."""
        if session_id in self.sessions:
            self.sessions[session_id]["last"] = time.time() - self.IDLE_SECONDS - 5


class AwsRuntime:
    """Calls the AskIT agent the trainer deployed on AgentCore Runtime."""
    label = "Trainer's Runtime (AWS)"

    def __init__(self, arn):
        self.arn = arn.strip()

    def invoke(self, prompt, session_id, provider, gateway_url=""):
        import boto3
        t0 = time.time()
        if not ARN_RE.match(self.arn):
            return RtResult(False, error="The Runtime ARN does not look right. It starts with arn:aws:bedrock-agentcore: and contains :runtime/ . Copy it again from the trainer.")
        try:
            client = boto3.client("bedrock-agentcore", region_name=region_of(self.arn))
            resp = client.invoke_agent_runtime(agentRuntimeArn=self.arn, runtimeSessionId=session_id,
                                               payload=json.dumps({"prompt": prompt, "gateway_url": gateway_url}).encode("utf-8"))
        except Exception as e:                                                    # noqa: BLE001
            return RtResult(False, ms=int((time.time() - t0) * 1000), error=explain(e))
        ms = int((time.time() - t0) * 1000)
        try:
            body = resp.get("response")
            raw = body.read() if hasattr(body, "read") else b"".join(c for c in body)
            text = raw.decode("utf-8", "replace")
            if "text/event-stream" in resp.get("contentType", ""):
                text = "".join(line[6:] for line in text.splitlines() if line.startswith("data: ")) or text
            data = json.loads(text)
        except Exception as e:                                                    # noqa: BLE001
            return RtResult(False, ms=ms, error=f"The Runtime answered, but not in the shape this lab expects ({type(e).__name__}). Tell the trainer.", raw=locals().get("text"))
        if isinstance(data, str):
            data = {"answer": data}
        if data.get("error"):
            return RtResult(False, ms=ms, error="The agent in the Runtime reported: " + str(data["error"]), raw=data)
        sess = data.get("session", {})
        return RtResult(True, data.get("answer", ""), data.get("steps", []), ms, data.get("tokens_in", 0), data.get("tokens_out", 0), data.get("cost_usd", 0.0), sess, raw=data)


def explain(e):
    """Plain-English hint for the errors people meet most."""
    code = getattr(getattr(e, "response", None), "get", lambda *_: {})("Error", {}).get("Code", "") if hasattr(e, "response") else ""
    hint = {"AccessDeniedException": "Your AWS user may not call this Runtime (it needs bedrock-agentcore:InvokeAgentRuntime), or the region is wrong. Tell the trainer: AccessDenied on Runtime.",
            "ResourceNotFoundException": "No Runtime with this ARN. Copy it again from the trainer.",
            "ThrottlingException": "Too many calls at once. Wait ten seconds and try again.",
            "ValidationException": "AWS did not like the request (often a bad ARN or session id).",
            "RuntimeClientError": "The agent code inside the Runtime crashed. Tell the trainer.",
            "NoCredentialsError": "No AWS keys found. Check the .env file in the course folder."}.get(code or type(e).__name__, "")
    return f"{code or type(e).__name__}: {str(e)[:260]}. {hint}".strip()
